result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/src/gem.js", "content": "import { BufferGeometry, BufferAttribute, Vector3 } from 'three';

/**
 * Build a faceted gemstone geometry:
 *  - top apex at (0, crownHeight, 0)
 *  - ring of `facets` vertices on the girdle circle at y = 0
 *  - bottom apex at (0, -pavilionDepth, 0)
 *
 * Non-indexed: every triangle carries its own vertices so each facet is
 * flat-shaded after computeVertexNormals().
 */
export function buildGem({
  facets = 8,
  crownHeight = 1,
  pavilionDepth = 1.4,
  girdleRadius = 1,
} = {}) {
  const apexTop = [0, crownHeight, 0];
  const apexBottom = [0, -pavilionDepth, 0];

  // Girdle ring vertices (CCW when viewed from above).
  const girdle = [];
  for (let i = 0; i < facets; i++) {
    const theta = (i / facets) * Math.PI * 2;
    girdle.push([girdleRadius * Math.cos(theta), 0, girdleRadius * Math.sin(theta)]);
  }

  const positions = [];

  const pushTri = (a, b, c) => {
    positions.push(...a, ...b, ...c);
  };

  for (let i = 0; i < facets; i++) {
    const p0 = girdle[i];
    const p1 = girdle[(i + 1) % facets];
    // Crown facet: wound so its normal points outward and up.
    pushTri(apexTop, p1, p0);
    // Pavilion facet: wound so its normal points outward and down.
    pushTri(apexBottom, p0, p1);
  }

  const geo = new BufferGeometry();
  geo.setAttribute('position', new BufferAttribute(new Float32Array(positions), 3));
  geo.computeVertexNormals();
  return geo;
}

/** Triangle count and axis-aligned bounding box of a geometry. */
export function gemStats(geo) {
  geo.computeBoundingBox();
  return {
    triangleCount: geo.attributes.position.count / 3,
    bbox: geo.boundingBox.clone(),
  };
}

/**
 * Unique per-face normals of a non-indexed geometry.
 * Directions are deduped within a tolerance of 1e-6 per component
 * (compared on the normalized direction).
 */
export function facetNormals(geo) {
  const pos = geo.attributes.position;
  const normals = [];
  const a = new Vector3();
  const b = new Vector3();
  const c = new Vector3();
  const ab = new Vector3();
  const cb = new Vector3();

  for (let i = 0; i < pos.count; i += 3) {
    a.fromBufferAttribute(pos, i);
    b.fromBufferAttribute(pos, i + 1);
    c.fromBufferAttribute(pos, i + 2);
    cb.subVectors(c, b);
    ab.subVectors(a, b);
    cb.cross(ab).normalize();
    if (!normals.some((n) => Math.abs(n.x - cb.x) < 1e-6 && Math.abs(n.y - cb.y) < 1e-6 && Math.abs(n.z - cb.z) < 1e-6)) {
      normals.push(cb.clone());
    }
  }
  return normals;
}
