result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/test/gem.test.js", "content": "import { describe, it, expect } from 'vitest';
import { buildGem, gemStats, facetNormals } from '../src/gem.js';

describe('buildGem', () => {
  const facets = 8;
  const crownHeight = 1;
  const pavilionDepth = 1.4;
  const girdleRadius = 1;
  const geo = buildGem({ facets, crownHeight, pavilionDepth, girdleRadius });

  it('has exactly 2*facets triangles', () => {
    const { triangleCount } = gemStats(geo);
    expect(triangleCount).toBe(2 * facets);
  });

  it('bbox height is crownHeight + pavilionDepth and xz extent is 2*girdleRadius', () => {
    const { bbox } = gemStats(geo);
    expect(bbox.max.y - bbox.min.y).toBeCloseTo(crownHeight + pavilionDepth, 9);
    expect(bbox.max.x - bbox.min.x).toBeCloseTo(2 * girdleRadius, 9);
    expect(bbox.max.z - bbox.min.z).toBeCloseTo(2 * girdleRadius, 9);
    expect(bbox.min.y).toBeCloseTo(-pavilionDepth, 9);
    expect(bbox.max.y).toBeCloseTo(crownHeight, 9);
  });

  it('yields exactly 2*facets distinct facet normals', () => {
    const normals = facetNormals(geo);
    expect(normals.length).toBe(2 * facets);
  });

  it('upper-facet normals point up, lower-facet normals point down', () => {
    const normals = facetNormals(geo);
    const upper = normals.filter((n) => n.y > 0);
    const lower = normals.filter((n) => n.y < 0);
    expect(upper.length).toBe(facets);
    expect(lower.length).toBe(facets);
    for (const n of upper) expect(n.y).toBeGreaterThan(0);
    for (const n of lower) expect(n.y).toBeLessThan(0);
  });

  it('places every girdle vertex at radius girdleRadius', () => {
    const pos = geo.attributes.position;
    const seen = new Set();
    for (let i = 0; i < pos.count; i++) {
      const x = pos.getX(i);
      const y = pos.getY(i);
      const z = pos.getZ(i);
      if (Math.abs(y) < 1e-12 && (Math.abs(x) > 1e-12 || Math.abs(z) > 1e-12)) {
        seen.add(`${x},${z}`);
        const r = Math.hypot(x, z);
        expect(Math.abs(r - girdleRadius)).toBeLessThan(1e-9);
      }
    }
    expect(seen.size).toBe(facets);
  });
});
"})
